251	    /**
252	     * Count the members of the new owner's household after this create: the existing owners
253	     * that share the given owner's last name and address (compared case-insensitively with
254	     * collapsed whitespace, the same normalization used to derive the household identifier)
255	     * plus the owner being created. Invoked before the new owner is persisted.
256	     */
257	    private int countHouseholdMembers(Owner owner) {
258	        String normalizedLastName = normalizeHouseholdField(owner.getLastName());
259	        String normalizedAddress = normalizeHouseholdField(owner.getAddress());
260	        long existing = ownerRepository.findAll().stream()
261	            .filter(other -> normalizeHouseholdField(other.getLastName()).equals(normalizedLastName)
262	                && normalizeHouseholdField(other.getAddress()).equals(normalizedAddress))
263	            .count();
264	        return (int) existing + 1;
265	    }
266	
267	    /**
268	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields
269	     * can be compared case-insensitively with collapsed whitespace. A {@code null} value
270	     * normalizes to the empty string.
271	     */
272	    private String normalizeHouseholdField(String value) {
273	        if (value == null) {
274	            return "";
275	        }
276	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
277	    }
278	
279	    /**
280	     * Count the existing owners that share the given owner's first name and last name,
281	     * compared case-insensitively. Invoked before the new owner is persisted, so the
282	     * result is the number of namesakes that existed at the time of creation.
283	     */
284	    private int countNamesakes(Owner owner) {
285	        String firstName = owner.getFirstName();
286	        String lastName = owner.getLastName();
287	        if (firstName == null || lastName == null) {
288	            return 0;
289	        }
290	        return (int) ownerRepository.findAll().stream()
291	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
292	                && lastName.equalsIgnoreCase(existing.getLastName()))
293	            .count();
294	    }
295	
296	    /**
297	     * Build the owner's customer code in the form '<REGION>-<HASH8>' where REGION is the region
298	     * code derived from the owner's postcode (falling back to the city) and HASH8 is the first
299	     * 8 upper-case hex characters of the SHA-256 digest over the owner's normalized telephone
300	     * concatenated with the owner's last name. There is no sequence number: the identity is
301	     * derived entirely from the region and the telephone/last-name hash.
302	     */
303	    private String generateCustomerCode(Owner owner) {
304	        return regionFor(owner) + "-" + hash8(owner);
305	    }
306	
307	    /**
308	     * Derive the owner's region, preferring the postcode over the city. The postcode is looked up
309	     * against the canonical region ranges first ({@code NSW 2000-2099}, {@code VIC 3000-3099},
310	     * {@code QLD 4000-4099}); only when the postcode is absent or falls in no known range does the
311	     * derivation fall back to the fixed city-to-region table ({@code Sydney->NSW},
312	     * {@code Melbourne->VIC}, {@code Brisbane->QLD}). The result is {@code "UNKNOWN"} when neither
313	     * the postcode nor the city resolves to a region.
314	     */
315	    private String regionFor(Owner owner) {
316	        String region = regionFromPostcode(owner.getPostcode());
317	        if (region != null) {
318	            return region;
319	        }
320	        return regionFromCity(owner.getCity());
321	    }
322	
323	    /**
324	     * Look up the canonical region for a postcode by its range ({@code NSW 2000-2099},
325	     * {@code VIC 3000-3099}, {@code QLD 4000-4099}), returning {@code null} when the postcode is
326	     * absent, non-numeric or in no known range.
327	     */
328	    private String regionFromPostcode(String postcode) {
329	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
330	            return null;
331	        }
332	        int value = Integer.parseInt(postcode);
333	        if (value >= 2000 && value <= 2099) {
334	            return "NSW";
335	        }
336	        if (value >= 3000 && value <= 3099) {
337	            return "VIC";
338	        }
339	        if (value >= 4000 && value <= 4099) {
340	            return "QLD";
341	        }
342	        return null;
343	    }
344	
345	    /**
346	     * Look up the canonical region for a city using the fixed city-to-region table, returning
347	     * {@code "UNKNOWN"} when the city is absent or not in the table.
348	     */
349	    private String regionFromCity(String city) {
350	        if (city == null) {
351	            return "UNKNOWN";
352	        }
353	        return switch (city) {
354	            case "Sydney" -> "NSW";
355	            case "Melbourne" -> "VIC";
356	            case "Brisbane" -> "QLD";
357	            default -> "UNKNOWN";
358	        };
359	    }
360	
361	    /**
362	     * Compute the first 8 upper-case hex characters of the SHA-256 digest over the owner's
363	     * normalized telephone concatenated with the owner's last name.
364	     */
365	    private String hash8(Owner owner) {
366	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
367	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
368	        try {
369	            byte[] digest = MessageDigest.getInstance("SHA-256")
370	                .digest((telephone + lastName).getBytes(StandardCharsets.UTF_8));
371	            StringBuilder sb = new StringBuilder(8);
372	            for (int i = 0; i < 4; i++) {
373	                sb.append(String.format("%02X", digest[i]));
374	            }
375	            return sb.toString();
376	        }
377	        catch (NoSuchAlgorithmException ex) {
378	            throw new IllegalStateException("SHA-256 not available", ex);
379	        }
380	    }
381	
382	    @Override
