392	    }
393	
394	    @Override
395	    @Transactional(readOnly = true)
396	    public List<Specialty> findSpecialtiesByNameIn(Set<String> names) {
397	        return findEntityById(() -> specialtyRepository.findSpecialtiesByNameIn(names));
398	    }
399	
400	    private <T> T findEntityById(Supplier<T> supplier) {
401	        try {
402	            return supplier.get();
403	        } catch (ObjectRetrievalFailureException | EmptyResultDataAccessException e) {
404	            // Just ignore not found exceptions for Jdbc/Jpa realization
405	            return null;
406	        }
407	    }
408	
409	}
