19	/**
20	 * Maps Owner & OwnerDto using Mapstruct
21	 */
22	@Mapper(uses = PetMapper.class)
23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName",
26	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
27	    @Mapping(target = "initials",
28	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
29	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
30	    @Mapping(target = "householdId", expression = "java(householdId(owner))")
31	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
32	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
33	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
34	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
35	    @Mapping(target = "locality", expression = "java(locality(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
38	    OwnerDto toOwnerDto(Owner owner);
39	
40	    /**
41	     * Derives an owner's age band from its birth date, computed as the owner's age on its
42	     * {@link Owner#getRegistrationDate() registration date}: {@code "MINOR"} when under {@code 18},
43	     * {@code "ADULT"} when {@code 18} to {@code 64}, and {@code "SENIOR"} when {@code 65} or older.
44	     * Returns {@code null} when the owner has no birth date, so the field is omitted from the
45	     * response.
46	     *
47	     * @param owner the owner to derive the age band for
48	     * @return {@code "MINOR"}, {@code "ADULT"} or {@code "SENIOR"}, or {@code null} when no birth date
49	     *     is held
50	     */
51	    default String ageBand(Owner owner) {
52	        java.time.LocalDate birthDate = owner.getBirthDate();
53	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
54	        if (birthDate == null || registrationDate == null) {
55	            return null;
56	        }
57	        int age = java.time.Period.between(birthDate, registrationDate).getYears();
58	        if (age < 18) {
59	            return "MINOR";
60	        }
61	        return age < 65 ? "ADULT" : "SENIOR";
62	    }
63	
64	    /**
65	     * Derives an owner's preferred contact channel: {@code "EMAIL"} when the owner has a non-blank
66	     * email, otherwise {@code "PHONE"}.
67	     *
68	     * @param owner the owner to derive the contact preference for
69	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
70	     */
71	    default String contactPreference(Owner owner) {
72	        String email = owner.getEmail();
73	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
74	    }
75	
76	    /**
77	     * Derives an owner's locality from the region-and-hash customer code: the {@code <REGION>}
78	     * segment (everything before the first {@code '-'}) of the owner's {@code customerCode}. Because
79	     * the customer code's region is itself derived from the postcode (falling back to the city), the
80	     * locality now moves with the identity rather than being computed independently. The result is
81	     * {@code "UNKNOWN"} when no customer code is present.
82	     *
83	     * @param owner the owner to derive the locality for
84	     * @return the region segment of the customer code, or {@code "UNKNOWN"}
85	     */
86	    default String locality(Owner owner) {
87	        String code = owner.getCustomerCode();
88	        if (code == null || code.isEmpty()) {
89	            return "UNKNOWN";
90	        }
91	        int dash = code.indexOf('-');
92	        return dash < 0 ? code : code.substring(0, dash);
93	    }
94	
95	    /**
96	     * Derives an owner's numeric membership level, fixed at creation. Starts at {@code 1}, plus
97	     * {@code 1} when an email is present (non-blank), plus {@code 1} when the owner's namesake count
98	     * is {@code 0}, capped at {@code 3} (level {@code 4} is reserved for tenure).
99	     *
100	     * @param owner the owner to derive the membership level for
101	     * @return the membership level, between {@code 1} and {@code 3}
102	     */
103	    default Integer membershipLevel(Owner owner) {
104	        int level = 1;
105	        String email = owner.getEmail();
106	        if (email != null && !email.isBlank()) {
107	            level++;
108	        }
109	        Integer namesakeCount = owner.getNamesakeCount();
110	        if (namesakeCount != null && namesakeCount == 0) {
111	            level++;
112	        }
113	        return Math.min(level, 3);
114	    }
115	
116	    /**
117	     * Derives an owner's membership number, formatted {@code <customerCode>-M<YY>} where
118	     * {@code <customerCode>} is the owner's region-and-hash customer code and {@code YY} is the last
119	     * two digits (zero-padded) of the owner's registration date year (e.g. {@code NSW-1A2B3C4D-M26}).
120	     *
121	     * @param owner the owner to derive the membership number for
122	     * @return the formatted membership number
123	     */
124	    default String membershipNumber(Owner owner) {
125	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
126	        return owner.getCustomerCode() + "-M" + yy;
127	    }
128	
129	    /**
130	     * Derives an owner's check digit: a single Luhn check digit ({@code 0}-{@code 9}) computed over
131	     * the digits contained in the owner's customer code. Non-digit characters in the customer code
132	     * are ignored.
133	     *
134	     * @param owner the owner to derive the check digit for
135	     * @return the Luhn check digit, between {@code 0} and {@code 9}
136	     */
137	    default Integer checkDigit(Owner owner) {
138	        String code = owner.getCustomerCode();
139	        int sum = 0;
140	        boolean dbl = true;
141	        for (int i = code.length() - 1; i >= 0; i--) {
142	            char c = code.charAt(i);
143	            if (c < '0' || c > '9') {
144	                continue;
145	            }
146	            int d = c - '0';
147	            if (dbl) {
148	                d *= 2;
149	                if (d > 9) {
150	                    d -= 9;
151	                }
152	            }
153	            sum += d;
154	            dbl = !dbl;
155	        }
156	        return (10 - (sum % 10)) % 10;
157	    }
158	
159	    /**
160	     * Derives an owner's household identifier: a stable value shared by every owner with the same
161	     * last name and address (compared case-insensitively with collapsed whitespace). Because it is
162	     * derived deterministically from those fields, owners created via the {@code sharesHousehold}
163	     * flag - which by definition have a matching last name and address - receive the same value.
164	     *
165	     * @param owner the owner to derive the household identifier for
166	     * @return a {@code HH-} prefixed identifier, never blank
167	     */
168	    default String householdId(Owner owner) {
169	        String key = normalizeHouseholdField(owner.getLastName()) + ' '
170	            + normalizeHouseholdField(owner.getAddress());
171	        try {
172	            byte[] digest = MessageDigest.getInstance("SHA-256")
173	                .digest(key.getBytes(StandardCharsets.UTF_8));
174	            StringBuilder sb = new StringBuilder("HH-");
175	            for (int i = 0; i < 6; i++) {
176	                sb.append(String.format("%02X", digest[i]));
177	            }
178	            return sb.toString();
179	        }
180	        catch (NoSuchAlgorithmException ex) {
181	            throw new IllegalStateException("SHA-256 not available", ex);
182	        }
183	    }
184	
185	    /**
186	     * Derives an owner's identity key, into which all duplicate detection is consolidated. The key
187	     * is {@code <normalizedTelephone>|<email or empty>|<householdId>}: the owner's (already E.164
188	     * normalized) telephone, its (already lower-cased) email or the empty string when none is held,
189	     * and its {@link #householdId(Owner) household id}. Two owners are duplicates only when their
190	     * whole identity keys are equal; because the telephone is part of the key, household members with
191	     * different telephones have different keys.
192	     *
193	     * @param owner the owner to derive the identity key for
194	     * @return the {@code telephone|email|householdId} identity key
195	     */
196	    default String identityKey(Owner owner) {
197	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
198	        String email = owner.getEmail() == null ? "" : owner.getEmail();
199	        return telephone + '|' + email + '|' + householdId(owner);
200	    }
201	
202	    /**
203	     * Collapses surrounding and internal whitespace and lower-cases a value so household fields can
204	     * be compared case-insensitively with collapsed whitespace. A {@code null} value normalizes to
205	     * the empty string. Mirrors the normalization used when enforcing the household rule on create.
206	     *
207	     * <p>Declared {@code private} so MapStruct does not treat it as an implicit String-to-String
208	     * conversion and apply it to unrelated String properties (last name, address, ...).
209	     */
210	    private String normalizeHouseholdField(String value) {
211	        if (value == null) {
212	            return "";
213	        }
214	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
215	    }
216	
217	    Owner toOwner(OwnerDto ownerDto);
218	
219	    @Mapping(target = "id", ignore = true)
220	    @Mapping(target = "pets", ignore = true)
221	    Owner toOwner(OwnerFieldsDto ownerDto);
222	
223	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
224	
225	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
226	
227	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
228	        OwnerPageDto ownerPageDto = new OwnerPageDto();
229	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
230	        ownerPageDto.setPage(ownerPage.getNumber());
231	        ownerPageDto.setSize(ownerPage.getSize());
232	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
233	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
234	        return ownerPageDto;
235	    }
