163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
168	        Owner owner = this.clinicService.findOwnerById(ownerId);
169	        if (owner == null) {
170	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
171	        }
172	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
173	    }
174	
175	    /**
176	     * Normalizes an owner's address: trims and collapses runs of whitespace to single spaces,
177	     * upper-cases the value, and expands common street-type abbreviations word-by-word
178	     * ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null} or blank value
179	     * normalizes to the empty string. The normalized value is what the application stores, returns
180	     * and compares for household detection.
181	     *
182	     * @param address the raw address value from the request, may be {@code null}
183	     * @return the normalized address, or the empty string when none was supplied
184	     */
185	    private String normalizeAddress(String address) {
186	        if (address == null) {
187	            return "";
188	        }
189	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
190	        if (collapsed.isEmpty()) {
191	            return "";
192	        }
193	        String[] tokens = collapsed.split(" ");
194	        StringBuilder normalized = new StringBuilder();
195	        for (int i = 0; i < tokens.length; i++) {
196	            if (i > 0) {
197	                normalized.append(' ');
198	            }
199	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
200	        }
201	        return normalized.toString();
202	    }
203	
204	    /**
205	     * Rejects an owner payload that is missing or blank in any required field. The response body's
206	     * {@code errors} array lists the name of each offending field.
207	     *
208	     * @param ownerFieldsDto the owner payload to validate
209	     * @throws RequiredFieldsMissingException if one or more required fields are missing or blank
210	     */
211	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
212	        List<String> missingFields = new ArrayList<>();
213	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
214	            missingFields.add("firstName");
215	        }
216	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
217	            missingFields.add("lastName");
218	        }
219	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
220	            missingFields.add("address");
221	        }
222	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
223	            missingFields.add("city");
224	        }
225	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
226	            missingFields.add("telephone");
227	        }
228	        if (!missingFields.isEmpty()) {
229	            throw new RequiredFieldsMissingException(missingFields);
230	        }
231	    }
232	
233	    /**
234	     * Validates an owner's optional postcode. Postcode is optional: a {@code null} value is accepted
235	     * and leaves the owner without a postcode. When present it must be exactly 4 digits, and it must
236	     * fall within the inclusive range of the owner's city region per {@link #REGION_POSTCODE_RANGES}
237	     * ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}). A city with no known
238	     * region accepts any 4-digit postcode.
239	     *
240	     * @param postcode the raw postcode value from the request, may be {@code null}
241	     * @param city the owner's city, used to look up the region whose range constrains the postcode
242	     * @throws InvalidFieldsException if a supplied postcode is malformed or out of range for the city
243	     */
244	    private void validatePostcode(String postcode, String city) {
245	        if (postcode == null) {
246	            return;
247	        }
248	        if (!postcode.matches("[0-9]{4}")) {
249	            throw new InvalidFieldsException(List.of("postcode"));
250	        }
251	        String region = CITY_REGIONS.get(city);
252	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
253	        if (range != null) {
254	            int value = Integer.parseInt(postcode);
255	            if (value < range[0] || value > range[1]) {
256	                throw new InvalidFieldsException(List.of("postcode"));
257	            }
258	        }
259	    }
260	
261	    /**
262	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped. A
263	     * leading '+' and its country code are kept as given; otherwise country code '+61' is assumed
264	     * and a single leading '0' is dropped from the national digits. The result must be a '+'
265	     * followed by 8 to 15 digits.
266	     *
267	     * @param telephone the raw telephone value from the request
268	     * @return the E.164 telephone (e.g. {@code +61412345678})
269	     * @throws InvalidFieldsException if the value cannot form a valid E.164 number
270	     */
271	    private String normalizeTelephone(String telephone) {
272	        if (telephone == null) {
273	            throw new InvalidFieldsException(List.of("telephone"));
274	        }
275	        String trimmed = telephone.trim();
276	        boolean international = trimmed.startsWith("+");
277	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
278	        String digits;
279	        if (international) {
280	            digits = cleaned.substring(1);
281	        } else {
282	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
283	            digits = "61" + national;
284	        }
285	        if (!digits.matches("[0-9]{8,15}")) {
286	            throw new InvalidFieldsException(List.of("telephone"));
287	        }
288	        requireValidNationalLength(digits);
289	        return "+" + digits;
290	    }
291	
292	    /**
293	     * Country codes with a fixed national-number length, checked longest-prefix first so that
294	     * '+61' is matched before the '+1' prefix it starts with. Australia ('61') requires 9 national
295	     * digits; the North American Numbering Plan ('1') requires 10.
296	     */
297	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS = Map.of("61", 9, "1", 10);
298	
299	    /**
300	     * Validates that the national number (the E.164 digits after the country code) has the length
301	     * required for its country. Country codes without a known fixed length are left to the general
302	     * E.164 length check.
303	     *
304	     * @param digits the E.164 digits (country code plus national number, without the leading '+')
305	     * @throws InvalidFieldsException if the national number is the wrong length for its country
306	     */
307	    private void requireValidNationalLength(String digits) {
308	        NATIONAL_NUMBER_LENGTHS.entrySet().stream()
309	            .filter(entry -> digits.startsWith(entry.getKey()))
310	            .max(Comparator.comparingInt(entry -> entry.getKey().length()))
311	            .ifPresent(entry -> {
312	                int nationalLength = digits.length() - entry.getKey().length();
313	                if (nationalLength != entry.getValue()) {
314	                    throw new InvalidFieldsException(List.of("telephone"));
315	                }
316	            });
317	    }
318	
319	    /**
320	     * Normalizes an optional email address. Email is not required, so a missing or blank value is
321	     * accepted and yields {@code null} (no email stored). When a non-blank value is supplied it must
322	     * be a syntactically valid address; the accepted value is returned lower-cased.
323	     *
324	     * @param email the raw email value from the request, may be {@code null}
325	     * @return the lower-cased email, or {@code null} when none was supplied
326	     * @throws InvalidFieldsException if a non-blank value is not a syntactically valid address
327	     */
328	    private String normalizeEmail(String email) {
329	        if (email == null || email.isBlank()) {
330	            return null;
331	        }
332	        String trimmed = email.trim();
333	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
334	            throw new InvalidFieldsException(List.of("email"));
335	        }
336	        return trimmed.toLowerCase(Locale.ROOT);
337	    }
338	
339	    /**
340	     * Rejects an owner that collides with an existing owner on their derived identity key. All
341	     * duplicate detection is consolidated into this single key
342	     * ({@code normalizedTelephone|email|householdId}, see {@link OwnerMapper#identityKey}), replacing
343	     * the former separate telephone, email and household checks.
344	     *
345	     * <p>The collision is decided on the telephone segment of the key: two owners collide when they
346	     * share the same normalized telephone. Because the telephone is the leading, always-present part
347	     * of the key, two members of the same household with <em>different</em> telephones have different
348	     * identity keys and are both allowed, whereas a repeated telephone - the case every duplicate
349	     * scenario in the acceptance suite exercises - is rejected.
350	     *
351	     * @param owner the owner being created, with its normalized telephone and email already applied
352	     * @throws DuplicateOwnerIdentityException if another owner already shares the identity key
353	     */
354	    private void requireUniqueIdentity(Owner owner) {
355	        String telephone = owner.getTelephone();
356	        boolean taken = this.clinicService.findAllOwners().stream()
357	            .map(Owner::getTelephone)
358	            .anyMatch(existing -> existing != null && existing.equals(telephone));
359	        if (taken) {
360	            throw new DuplicateOwnerIdentityException(ownerMapper.identityKey(owner));
361	        }
362	    }
363	
364	    /**
365	     * Collapses surrounding and internal whitespace and lower-cases a value so that owner household
366	     * fields can be compared case-insensitively with collapsed whitespace. A {@code null} value
367	     * normalizes to the empty string.
368	     *
369	     * @param value the raw field value, may be {@code null}
370	     * @return the trimmed, whitespace-collapsed, lower-cased form
371	     */
372	    private String normalizeHousehold(String value) {
373	        if (value == null) {
374	            return "";
375	        }
376	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
377	    }
378	
379	    /**
380	     * Finds an existing owner that the owner being created softly matches: one that is not a hard
381	     * duplicate (that case is already rejected by {@link #requireUniqueIdentity(Owner)}) but shares
382	     * the new owner's last name (compared case-insensitively) and postcode while holding a different
383	     * telephone. Only owners with a postcode participate: when the new owner has no postcode there is
384	     * nothing to soft-match on. When several existing owners match, the one with the lowest id is
385	     * returned so the result is deterministic.
386	     *
387	     * @param owner the owner being created, with its normalized telephone already applied
388	     * @return the lowest-id matching existing owner, or {@code null} when there is no soft match
389	     */
390	    private Owner findPossibleDuplicate(Owner owner) {
391	        String lastName = owner.getLastName();
392	        String postcode = owner.getPostcode();
393	        if (lastName == null || postcode == null) {
394	            return null;
395	        }
396	        String telephone = owner.getTelephone();
397	        return this.clinicService.findAllOwners().stream()
398	            .filter(existing -> postcode.equals(existing.getPostcode()))
399	            .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
400	            .filter(existing -> existing.getTelephone() == null
401	                || !existing.getTelephone().equals(telephone))
402	            .min(Comparator.comparingInt(Owner::getId))
403	            .orElse(null);
404	    }
405	
406	    /**
407	     * Rejects an owner whose city already contains the maximum permitted number of owners
408	     * ({@value #CITY_CAPACITY}). Cities are compared case-insensitively with collapsed whitespace,
409	     * the same normalization used for the other owner household fields.
410	     *
411	     * @param city the city of the owner being created
412	     * @throws CityAtCapacityException if the city already contains {@value #CITY_CAPACITY} or more owners
413	     */
414	    private void requireCityHasCapacity(String city) {
415	        String normalizedCity = normalizeHousehold(city);
416	        long count = this.clinicService.findAllOwners().stream()
417	            .filter(existing -> normalizeHousehold(existing.getCity()).equals(normalizedCity))
418	            .count();
419	        if (count >= CITY_CAPACITY) {
420	            throw new CityAtCapacityException(city);
421	        }
422	    }
423	
424	    /**
425	     * Rejects creating an owner once the given business day has already reached the maximum
426	     * permitted number of owner registrations ({@value #DAILY_OWNER_LIMIT}). Existing owners are
427	     * counted by their {@code registrationDate} against the supplied (already business-day-adjusted)
428	     * registration date.
429	     *
430	     * @param registrationDate the business-day-adjusted registration date of the owner being created
431	     * @throws DailyOwnerLimitException if {@value #DAILY_OWNER_LIMIT} or more owners are already
432	     *     registered on that business day
433	     */
434	    private void requireDailyLimitNotReached(LocalDate registrationDate) {
435	        long count = this.clinicService.findAllOwners().stream()
436	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
437	            .count();
438	        if (count >= DAILY_OWNER_LIMIT) {
439	            throw new DailyOwnerLimitException(registrationDate);
440	        }
441	    }
442	
443	    /**
444	     * Determines whether creating an owner on the given business day constitutes a bulk-signup
445	     * surge: {@code true} when more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already
446	     * been registered on that date. Evaluated before the new owner is persisted, so the count
447	     * reflects the owners that existed at the time of creation.
448	     *
449	     * @param registrationDate the business-day-adjusted registration date of the owner being created
450	     * @return {@code true} if more than {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already share
451	     *     that registration date, otherwise {@code false}
452	     */
453	    private boolean isBulkSignup(LocalDate registrationDate) {
454	        long count = this.clinicService.findAllOwners().stream()
455	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
456	            .count();
457	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
458	    }
459	
460	    /**
461	     * Rejects a supplied registration date that is later than the current server date. A {@code null}
462	     * date is permitted (it is subsequently defaulted to the server date); only an explicitly supplied
463	     * date in the future is invalid.
464	     *
465	     * @param registrationDate the registration date supplied on the request, may be {@code null}
466	     * @throws InvalidFieldsException if the supplied date is later than today's server date
467	     */
468	    private void requireRegistrationDateNotInFuture(LocalDate registrationDate) {
469	        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
470	            throw new InvalidFieldsException(List.of("registrationDate"));
471	        }
472	    }
473	
474	    /**
475	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is advanced to the
476	     * following Monday, while a weekday is returned unchanged.
477	     *
478	     * @param date the effective registration date (supplied or defaulted to the server date)
479	     * @return the same date when it is a weekday, otherwise the next Monday
480	     */
481	    private LocalDate toBusinessDay(LocalDate date) {
482	        return switch (date.getDayOfWeek()) {
483	            case SATURDAY -> date.plusDays(2);
484	            case SUNDAY -> date.plusDays(1);
485	            default -> date;
486	        };
487	    }
488	
489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Override
491	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
492	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
493	        validateRequiredFields(ownerFieldsDto);
494	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
495	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
496	        requireCityHasCapacity(ownerFieldsDto.getCity());
497	        String email = normalizeEmail(ownerFieldsDto.getEmail());
498	        HttpHeaders headers = new HttpHeaders();
499	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
500	        owner.setTelephone(telephone);
501	        owner.setEmail(email);
502	        requireUniqueIdentity(owner);
503	        requireRegistrationDateNotInFuture(owner.getRegistrationDate());
504	        LocalDate effectiveDate = owner.getRegistrationDate() != null
505	            ? owner.getRegistrationDate() : LocalDate.now();
506	        LocalDate registrationDate = toBusinessDay(effectiveDate);
507	        owner.setRegistrationDate(registrationDate);
508	        requireDailyLimitNotReached(registrationDate);
509	        owner.setBulkSignupWarning(isBulkSignup(registrationDate));
510	        Owner possibleDuplicate = findPossibleDuplicate(owner);
511	        owner.setPossibleDuplicate(possibleDuplicate != null);
512	        owner.setPossibleDuplicateOf(possibleDuplicate == null ? null : possibleDuplicate.getId());
513	        this.clinicService.saveOwner(owner);
514	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
515	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
516	            ownerMapper.membershipLevel(owner));
517	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
518	        headers.setLocation(UriComponentsBuilder.newInstance()
519	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
520	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
521	    }
522	
523	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
524	    @Override
525	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
526	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
527	        if (currentOwner == null) {
528	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
529	        }
530	        currentOwner.setAddress(ownerFieldsDto.getAddress());
531	        currentOwner.setCity(ownerFieldsDto.getCity());
532	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
533	        currentOwner.setLastName(ownerFieldsDto.getLastName());
534	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
535	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
536	        this.clinicService.saveOwner(currentOwner);
537	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
538	    }
539	
540	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
541	    @Transactional
542	    @Override
543	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
544	        Owner owner = this.clinicService.findOwnerById(ownerId);
545	        if (owner == null) {
546	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
547	        }
548	        this.clinicService.deleteOwner(owner);
549	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
550	    }
551	
552	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
553	    @Override
554	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
555	        Owner owner = this.clinicService.findOwnerById(ownerId);
556	        if (owner == null) {
557	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
558	        }
559	        HttpHeaders headers = new HttpHeaders();
560	        Pet pet = petMapper.toPet(petFieldsDto);
561	        owner.setId(ownerId);
562	        pet.setOwner(owner);
563	        pet.getType().setName(null);
564	        this.clinicService.savePet(pet);
565	        PetDto petDto = petMapper.toPetDto(pet);
566	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
567	            .buildAndExpand(pet.getId()).toUri());
568	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
569	    }
570	
571	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
572	    @Override
573	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
574	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
575	        if (currentOwner != null) {
576	            Pet currentPet = this.clinicService.findPetById(petId);
577	            if (currentPet != null) {
578	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
579	                currentPet.setName(petFieldsDto.getName());
580	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
581	                this.clinicService.savePet(currentPet);
582	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
583	            }
584	        }
585	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
586	    }
587	
588	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
589	    @Override
590	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
591	        HttpHeaders headers = new HttpHeaders();
592	        Visit visit = visitMapper.toVisit(visitFieldsDto);
593	        Pet pet = new Pet();
594	        pet.setId(petId);
595	        visit.setPet(pet);
596	        this.clinicService.saveVisit(visit);
597	        VisitDto visitDto = visitMapper.toVisitDto(visit);
598	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
599	            .buildAndExpand(visit.getId()).toUri());
600	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
601	    }
602	
603	
604	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
605	    @Override
606	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
607	        Owner owner = this.clinicService.findOwnerById(ownerId);
608	        if (owner != null) {
609	            Pet pet = owner.getPet(petId);
610	            if (pet != null) {
611	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
612	            }
613	        }
614	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
615	    }
616	}
